(()=>{'use strict';const s=document.querySelector('.result-scenes'),stage=s.querySelector('.result-stage'),cards=[...s.querySelectorAll('[data-result-card]')],copies=[...s.querySelectorAll('[data-result-copy]')],tabs=[...s.querySelectorAll('[data-result-step]')],reduced=matchMedia('(prefers-reduced-motion:reduce)');let frame=0,previous=-1;function render(){frame=0;const r=s.getBoundingClientRect(),p=Math.max(0,Math.min(.999,-r.top/Math.max(1,s.offsetHeight-stage.offsetHeight))),n=Math.floor(p*4);if(n===previous)return;previous=n;cards.forEach((c,i)=>{c.classList.toggle('active',i===n);c.setAttribute('aria-hidden',String(i!==n));copies[i].classList.toggle('active',i===n);copies[i].setAttribute('aria-hidden',String(i!==n));tabs[i].setAttribute('aria-current',i===n?'step':'false')});if(innerWidth<1000)tabs[n].parentElement.scrollTo({left:tabs[n].offsetLeft-16,behavior:reduced.matches?'instant':'smooth'})}function queue(){if(!frame)frame=requestAnimationFrame(render)}tabs.forEach((b,i)=>b.onclick=()=>scrollTo({top:s.getBoundingClientRect().top+scrollY+((i+.1)/4)*(s.offsetHeight-stage.offsetHeight),behavior:reduced.matches?'instant':'smooth'}));addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);render()})();
